// Prints the bundle that supabase/functions/mcp/index.ts should be for the current sources, to stdout.
// Writes nothing. The options mirror the ones in @lovable.dev/mcp-js/stacks/supabase/vite, which generates
// that file on Lovable; src/test/mcpBundleFreshness.test.ts compares the two. Run by the test in plain
// Node, because esbuild cannot run inside the jsdom test environment.
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { build } from "esbuild";

const ROOT = process.cwd();
const BANNER =
  "// AUTO-GENERATED by @lovable.dev/mcp-js — do not edit. Regenerated by the Vite plugin.\n" +
  "// To take ownership, delete this banner line; the plugin then leaves the file alone.";

const mcpVersion = JSON.parse(readFileSync(resolve(ROOT, "node_modules/@lovable.dev/mcp-js/package.json"), "utf8")).version;
const pkg = JSON.parse(readFileSync(resolve(ROOT, "package.json"), "utf8"));
const versions = { ...pkg.peerDependencies, ...pkg.devDependencies, ...pkg.dependencies };

// Mirrors the plugin's npmSpecifierFor: bare imports stay external, as npm: specifiers.
const npmSpecifierFor = (bare) => {
  const name = bare.startsWith("@") ? bare.split("/").slice(0, 2).join("/") : bare.split("/")[0];
  const subpath = bare.slice(name.length);
  if (name === "@lovable.dev/mcp-js") return `npm:${name}@${mcpVersion}${subpath}`;
  const range = versions[name];
  return range && /^[\dv^~>=]|^latest$/.test(range) ? `npm:${name}@${range}${subpath}` : `npm:${name}${subpath}`;
};

const externalizeBareAsNpm = {
  name: "externalize-bare-as-npm",
  setup(b) {
    b.onResolve({ filter: /.*/ }, (args) => {
      if (args.path.startsWith(".") || args.path.startsWith("/")) return null;
      if (/^(npm|node|jsr|https?|data):/.test(args.path)) return { path: args.path, external: true };
      return { path: npmSpecifierFor(args.path), external: true };
    });
  },
};

// The plugin passes the entry as an absolute path, which esbuild treats as a bare package on Windows
// (the cause of the stub a local Windows build writes). A virtual /src/ path gives the same bundle everywhere.
const virtualSrc = {
  name: "virtual-src",
  setup(b) {
    b.onResolve({ filter: /^\/src\// }, (args) => ({ path: resolve(ROOT, args.path.slice(1)) }));
  },
};

const result = await build({
  stdin: {
    contents:
      `import mcp from "/src/lib/mcp/index.ts";\n` +
      `import { createSupabaseHandler } from "@lovable.dev/mcp-js/stacks/supabase";\n` +
      `Deno.serve(createSupabaseHandler(mcp, { functionName: "mcp" }));\n`,
    resolveDir: ROOT,
    sourcefile: "lovable-mcp-supabase-entry.ts",
    loader: "ts",
  },
  bundle: true,
  write: false,
  format: "esm",
  platform: "neutral",
  target: "esnext",
  absWorkingDir: ROOT,
  logLevel: "silent",
  plugins: [virtualSrc, externalizeBareAsNpm],
});

process.stdout.write(
  `${BANNER}\n// supabase function: mcp\n// Bundled from src/lib/mcp/index.ts by @lovable.dev/mcp-js.\n${result.outputFiles[0].text}`,
);
